def longest_prefix(s):
    n = len(s)
    for length in range(n - 1, 0, -1):                       # try the longest possible length first
        if s[:length] == s[n - length:]:
            return s[:length]                                     # direct comparison of prefix and suffix
    return ""


if __name__ == "__main__":
    s = "ababab"
    print(longest_prefix(s))

