public class Main {
    String longestPrefix(String s) {
        int n = s.length();
        for (int length = n - 1; length > 0; length--) {          // try the longest possible length first
            if (s.substring(0, length).equals(s.substring(n - length))) {
                return s.substring(0, length);                          // direct comparison of prefix and suffix
            }
        }
        return "";
    }

    public static void main(String[] args) {
        String s = "ababab";
        Main solution = new Main();
        System.out.println(solution.longestPrefix(s));
    }
}

