def longest_prefix(s):
    n = len(s)
    lps = [0] * n                                            # longest proper prefix which is also a suffix
    length = 0
    i = 1
    while i < n:
        if s[i] == s[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    return s[:lps[n - 1]]


if __name__ == "__main__":
    s = "ababab"
    print(longest_prefix(s))

